SET NOCOUNT ON;
DBCC USEROPTIONS WITH NO_INFOMSGS;
SELECT DB_NAME() AS database_name, compatibility_level, is_read_committed_snapshot_on, snapshot_isolation_state_desc FROM sys.databases WHERE name=DB_NAME();
SELECT s.name AS schema_name,t.name AS table_name,p.rows FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.partitions p ON p.object_id=t.object_id AND p.index_id IN (0,1) ORDER BY t.name;
SELECT t.name AS table_name,c.name AS column_name,ty.name AS type_name,c.max_length,c.precision,c.scale,c.is_nullable,d.definition AS default_value FROM sys.columns c JOIN sys.tables t ON t.object_id=c.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id LEFT JOIN sys.default_constraints d ON d.object_id=c.default_object_id ORDER BY t.name,c.column_id;
SELECT OBJECT_NAME(parent_object_id) AS table_name,name,definition,is_disabled,is_not_trusted FROM sys.check_constraints ORDER BY table_name,name;
SELECT OBJECT_NAME(parent_object_id) AS table_name,name,OBJECT_NAME(referenced_object_id) AS referenced_table,delete_referential_action_desc,update_referential_action_desc,is_disabled,is_not_trusted FROM sys.foreign_keys ORDER BY table_name,name;
SELECT OBJECT_NAME(object_id) AS table_name,name,is_unique,is_primary_key,filter_definition FROM sys.indexes WHERE object_id IN (SELECT object_id FROM sys.tables) ORDER BY table_name,name;
SELECT name,type_desc FROM sys.objects WHERE type IN ('TR','P','FN','IF','TF') AND is_ms_shipped=0;
SELECT 'negative_stock' AS invariant, COUNT(*) AS violations FROM dbo.store_products WHERE quantity<0 OR reserved_quantity<0 OR reserved_quantity>quantity;
SELECT 'order_totals' AS invariant,COUNT(*) AS violations FROM dbo.orders o WHERE o.total_amount <> o.shipping_fee + (SELECT COALESCE(SUM(i.subtotal),0) FROM dbo.order_items i WHERE i.order_id=o.order_id);
SELECT 'item_subtotals' AS invariant,COUNT(*) AS violations FROM dbo.order_items WHERE subtotal<>unit_price*quantity;
SELECT 'payment_amounts' AS invariant,COUNT(*) AS violations FROM dbo.payments p JOIN dbo.orders o ON o.order_id=p.order_id WHERE p.amount<>o.total_amount;
SELECT 'fulfillment_store' AS invariant,COUNT(*) AS violations FROM dbo.order_items i JOIN dbo.order_fulfillments f ON f.fulfillment_id=i.fulfillment_id JOIN dbo.store_products sp ON sp.store_product_id=i.store_product_id WHERE f.order_id<>i.order_id OR f.store_id<>sp.store_id;
SELECT 'movement_arithmetic' AS invariant,COUNT(*) AS violations FROM dbo.inventory_movements WHERE CONVERT(bigint,quantity_before)+quantity_change<>quantity_after;
SELECT 'duplicate_successful_collection' AS invariant,COUNT(*) AS violations FROM (SELECT order_id FROM dbo.payments WHERE status='SUCCESS' GROUP BY order_id HAVING COUNT(*)>1) x;
DBCC CHECKCONSTRAINTS WITH ALL_CONSTRAINTS, NO_INFOMSGS;
SELECT 'constraint_scan_complete' AS result;
